<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { rich } from './rich'
import { app, act, say, gs, rollExpr } from '../session'
const tab = ref<'story' | 'log'>('story'), text = ref(''), box = ref<HTMLElement>(), near = ref(true); const dm = computed(() => app.role === 'dm' && !app.possess)
const down = () => nextTick(() => { const b = box.value; if (b && near.value) b.scrollTop = b.scrollHeight }); watch(() => [app.feed.length, app.log.length, tab.value, app.feedOpen, app.feed[app.feed.length - 1]?.text], down, { immediate: true }); const sc = () => { const b = box.value; if (b) near.value = b.scrollHeight - b.scrollTop - b.clientHeight < 60 }
const send = () => { if (!text.value.trim()) return; say(text.value); text.value = ''; near.value = true }; const key = (e: KeyboardEvent) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); (e.target as HTMLElement).blur() } if (e.key === 'Escape') (e.target as HTMLElement).blur() }; const chip = (c: any) => { if (c.do) void act(c.do, app.seat); else if (c.say) say(c.say) }
const seen = ref(0); watch(() => app.feed.length, (n, o) => { if (!app.feedOpen && n > o) seen.value += n - o }); watch(() => app.feedOpen, v => { if (v) seen.value = 0 }); const chips = computed(() => app.chips.filter(c => c.do?.k !== 'talk')); const first = computed(() => app.feed.findIndex(b => b.k === 'read')); const hint = computed(() => dm.value ? 'Read aloud, or "speak" as the chosen figure. /r 2d6' : app.gm === 'ai' ? 'Say or do anything. /r d20+3' : 'Speak to the table. /r d20+3')
</script>
<template><section class="feed paper" :class="{ shut: !app.feedOpen }"><header><button :class="{ on: tab === 'story' && app.feedOpen }" @click="tab = 'story'; app.feedOpen = true">Story<i v-if="seen">{{ seen }}</i></button><button :class="{ on: tab === 'log' && app.feedOpen }" @click="tab = 'log'; app.feedOpen = true">Rolls</button><span class="grow" /><span v-if="app.mind.state === 'thinking'" class="think">thinking…</span><span v-else-if="app.mind.state === 'error'" class="err" v-tip="app.mind.why + ' The Storyteller has taken over.'">model away</span><button class="fold" :aria-label="app.feedOpen ? 'Fold' : 'Unfold'" @click="app.feedOpen = !app.feedOpen">{{ app.feedOpen ? '−' : '+' }}</button></header>
  <template v-if="app.feedOpen"><div v-show="tab === 'story'" ref="box" class="pg scroll" @scroll="sc"><p v-if="!app.feed.length" class="muted">{{ app.gm === 'ai' ? 'The tale has not begun.' : 'Nothing has been said yet.' }}</p><template v-for="(b, i) in app.feed" :key="b.id"><p v-if="b.k === 'read'" class="read" :class="{ drop: i === first, wait: b.text === '…' }" v-html="rich(b.text)" /><p v-else-if="b.k === 'npc'" class="npc"><b>{{ b.who }}</b><span v-html="'“' + rich(b.text.replace(/^“|”$/g, '')) + '”'" /></p><p v-else-if="b.k === 'say' || b.k === 'do'" class="do"><b v-if="b.who" :style="{ '--c': b.color ?? 'var(--ink)' }">{{ b.who }}</b> {{ b.text }}</p><p v-else-if="b.k === 'ooc'" class="ooc"><b>{{ b.who }}</b> {{ b.text }}</p><p v-else-if="b.k === 'whisper'" class="wh"><b>For you alone</b>{{ b.text }}</p><p v-else class="sys" v-html="rich(b.text)" /></template></div>
  <div v-if="tab === 'log'" ref="box" class="pg log scroll" @scroll="sc"><p v-if="!app.log.length" class="muted">No dice have fallen yet.</p><div v-for="e in app.log" :key="e.id" class="e" :class="[e.t, { ok: e.ok, no: e.ok === false && e.dc }]"><template v-if="e.dice?.length && e.total !== undefined"><div class="l"><span class="cut"><b>{{ e.who }}</b> {{ e.label }}</span><span class="x"><i v-for="(q, k) in e.dice.slice(0, 8)" :key="k" :class="{ drop: q.drop, hi: q.v === q.d, lo: q.v === 1 }">{{ q.v }}</i>{{ (e.sum ?? '').replace(/^\d+ ?/, '') }}<template v-if="e.dc && (e.t !== 'attack' || e.ok !== undefined)"> against {{ app.role === 'dm' || gs?.chars[e.dst ?? e.src ?? ''] || e.t !== 'attack' ? e.dc : '?' }}</template><template v-if="e.t === 'attack' && e.ok">, {{ e.parts?.map(p => `${p.n} ${p.type}`).join(', ') }}</template></span></div><b class="tot">{{ e.total }}</b></template><span v-else class="l">{{ e.text }}</span></div></div>
  <div v-if="tab === 'log'" class="dd"><button v-for="d in [4, 6, 8, 10, 12, 20, 100]" :key="d" @click="rollExpr('d' + d)">d{{ d }}</button></div><div v-if="tab === 'story' && chips.length && !gs?.combat && !dm" class="cps"><button v-for="c in chips" :key="c.text" @click="chip(c)">{{ c.text }}</button></div><form class="in" @submit.prevent="send"><textarea v-model="text" rows="1" class="field" :placeholder="hint" aria-label="Say or do" maxlength="600" @keydown="key" /><button class="snd" aria-label="Send" type="submit">Say</button></form></template></section></template>
<style scoped>
.feed{display:flex;flex-direction:column;min-height:0;pointer-events:auto}header{display:flex;align-items:stretch;border-top:6px solid var(--ink);border-bottom:2px solid var(--ink);min-height:42px;flex:none}header button{white-space:nowrap;padding:0 15px;font:700 21px/1 var(--serif);color:var(--ink3)}header button:hover{color:var(--ink)}header .on{color:var(--ink)}header i{font:600 14px/20px var(--ui);background:var(--spot);color:var(--on-spot);padding:0 6px;margin-left:7px;display:inline-block}.fold{font:400 25px/1 var(--ui)!important;width:46px;text-align:center}.think,.err{align-self:center;font-size:15px;color:var(--ink2);animation:pulse 1.2s infinite}.err{animation:none;color:var(--bad)}
.pg{flex:1;min-height:0;padding:14px 18px 16px}.pg p{margin:0 0 11px}.read{font:400 18.5px/1.32 var(--serif)}.wait{animation:pulse 1s infinite}.npc{font:400 18.5px/1.3 var(--serif);padding-left:14px;border-left:5px solid var(--spot)}.npc b{display:block;font:600 15px/1.25 var(--ui)}.do,.ooc{font-size:16px;line-height:1.32;color:var(--ink2)}.do b{color:color-mix(in srgb,var(--c) 55%,#15171b);font-weight:600}.ooc{opacity:.75}.sys{font-size:15.5px;line-height:1.28;font-weight:500;border-top:1px solid var(--line2);border-bottom:1px solid var(--line2);padding:5px 0}.sys+.sys{border-top:0;margin-top:-11px}.wh{background:var(--ink);color:var(--paper);padding:8px 12px}.wh b{display:block;font-size:14px;opacity:.75;font-weight:500}
.e{display:flex;gap:10px;align-items:center;padding:5px 0;border-bottom:1px solid var(--line);font-size:16px;line-height:1.22}.e .l{flex:1;min-width:0;display:grid}.e b{font-weight:600}.x{color:var(--ink2);font-size:15px}.x i{font-style:normal;border:1.5px solid var(--ink3);padding:0 4px;margin-right:4px}.x .drop{opacity:.4;text-decoration:line-through}.x .hi{background:var(--ink);color:var(--paper)}.x .lo{background:var(--bad);color:#fff;border-color:var(--bad)}.tot{font:800 26px/1 var(--serif)!important;min-width:34px;text-align:right}.no .tot{color:var(--ink3)}
.dd,.cps{display:flex;flex-wrap:wrap;border-top:2px solid var(--ink);flex:none}.dd button{flex:1;text-align:center;padding:6px 0;border-right:1px solid var(--line)}.cps button{padding:6px 12px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);font-size:15.5px;line-height:1.15}.dd button:hover,.cps button:hover{background:var(--spot);color:var(--on-spot)}.cps{max-height:112px;overflow-y:auto;scrollbar-width:thin}.in{display:flex;border-top:2px solid var(--ink);flex:none}.in textarea{resize:none;min-height:46px;max-height:110px;field-sizing:content;border:0!important;padding:12px 16px;line-height:1.25;font-size:17px}.snd{padding:0 18px;font:700 20px/1 var(--serif);background:var(--ink);color:var(--paper)}.snd:hover{background:var(--spot);color:var(--on-spot)}
@media(max-width:899px){header{border-top-width:4px}.shut header{border-bottom:0}}
</style>
